style.css:
@-moz-document domain("example.com") {
/* Use 'button' to target all buttons, or a specific class like '.btn' */
    button {
        position: relative !important;
        padding: 12px 24px !important;
        background-color: #6c5ce7 !important;
        color: #ffffff !important;
        border-radius: 12px !important;
        border: none !important;
        cursor: pointer !important;
        font-weight: bold !important;
        
        /* 3D Depth using shadows */
        box-shadow: 0 4px 0 #4834d4, 0 8px 15px rgba(0, 0, 0, 0.2) !important;
        
        /* Smooth transition for the 'press' effect */
        transition: transform 0.1s ease, box-shadow 0.1s ease !important;
        
        /* Ensures scaling doesn't look blurry */
        backface-visibility: hidden;
    }

    /* Jelly Physics on Hover */
    button:hover {
        /* name | duration | timing-function | iteration-count */
        animation: jellyPhysics 0.6s ease-in-out 1;
    }

    /* 3D Press Effect on Click */
    button:active {
        transform: translateY(3px) !important;
        box-shadow: 0 1px 0 #4834d4, 0 2px 5px rgba(0, 0, 0, 0.3) !important;
    }

    /* The Jelly Logic */
    @keyframes jellyPhysics {
        0%   { transform: scale(1, 1); }
        30%  { transform: scale(1.25, 0.75); }
        40%  { transform: scale(0.75, 1.25); }
        50%  { transform: scale(1.15, 0.85); }
        65%  { transform: scale(0.95, 1.05); }
        75%  { transform: scale(1.05, 0.95); }
        100% { transform: scale(1, 1); }
    }
}
